import re
from collections import deque
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple


_HEADER_RE = re.compile(r"^\[(?P<id>[^\]]+)\]\s*$")
_CHOICE_RE = re.compile(r"^(?P<num>\d+)\.\s*(?P<text>.*?)\s*->\s*(?P<target>\S+)\s*$")
_LINE_RE = re.compile(r"^(?P<speaker>[^:]+):\s*(?P<body>.*)$")


@dataclass(frozen=True)
class Node:
    id: str
    text: str
    speaker: str
    type: str  # "line" | "choice"


@dataclass(frozen=True)
class Edge:
    from_: str
    to: str
    text: str

    def to_dict(self) -> Dict[str, str]:
        return {"from": self.from_, "to": self.to, "text": self.text}


def _escape_dot_label(s: str) -> str:
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def _split_sections(text: str) -> Tuple[List[str], Dict[str, List[str]]]:
    order: List[str] = []
    sections: Dict[str, List[str]] = {}

    current: Optional[str] = None
    for raw in text.splitlines():
        line = raw.strip("\n")
        header = _HEADER_RE.match(line.strip())
        if header:
            current = header.group("id").strip()
            if current not in sections:
                order.append(current)
                sections[current] = []
            continue
        if current is None:
            continue
        sections[current].append(line)

    return order, sections


def _parse_line_block(lines: List[str]) -> Tuple[str, str, Optional[str]]:
    cleaned = [ln.strip() for ln in lines if ln.strip()]
    if not cleaned:
        return "", "", None

    speakers: List[str] = []
    texts: List[str] = []
    targets: List[str] = []

    for ln in cleaned:
        m = _LINE_RE.match(ln)
        if not m:
            # Treat as narrator-like plain text.
            speakers.append("")
            body = ln
        else:
            speakers.append(m.group("speaker").strip())
            body = m.group("body").strip()

        target = None
        body_text = body
        if "->" in body:
            left, _, right = body.partition("->")
            body_text = left.strip()
            target = right.strip() or None

        if target:
            targets.append(target)

        if speakers[-1]:
            texts.append(body_text)
        else:
            texts.append(body_text)

    speaker = speakers[0] if speakers and all(s == speakers[0] for s in speakers) else ""
    if speaker:
        text = "\n".join(texts)
    else:
        # Preserve speaker labels in text if mixed/unknown.
        stitched = []
        for s, t in zip(speakers, texts):
            stitched.append(f"{s}: {t}" if s else t)
        text = "\n".join(stitched)

    next_id = targets[-1] if targets else None
    return speaker, text, next_id


def _parse_choice_block(lines: List[str]) -> List[Tuple[str, str]]:
    out: List[Tuple[str, str]] = []
    for ln in lines:
        ln = ln.strip()
        if not ln:
            continue
        m = _CHOICE_RE.match(ln)
        if not m:
            continue
        out.append((m.group("text").strip(), m.group("target").strip()))
    return out


def parse_script(text: str):
    """Parse dialogue script text into a JSON-serializable graph dict.

    Returns:
        {"nodes": [{"id","text","speaker","type"}, ...],
         "edges": [{"from","to","text"}, ...]}
    """

    order, sections = _split_sections(text)
    if not order:
        return {"nodes": [], "edges": []}

    nodes: Dict[str, Node] = {}
    edges: List[Edge] = []

    for sid in order:
        raw_lines = sections.get(sid, [])
        stripped = [ln.strip() for ln in raw_lines if ln.strip()]

        is_choice = any(_CHOICE_RE.match(ln) for ln in stripped)
        if is_choice:
            nodes[sid] = Node(id=sid, text="", speaker="", type="choice")
            for choice_text, target in _parse_choice_block(stripped):
                edges.append(Edge(from_=sid, to=target, text=choice_text))
        else:
            speaker, body_text, target = _parse_line_block(stripped)
            nodes[sid] = Node(id=sid, text=body_text, speaker=speaker, type="line")
            if target:
                edges.append(Edge(from_=sid, to=target, text=""))

    # Ensure all edge targets exist (create placeholders, commonly "End").
    referenced = {e.to for e in edges}
    for tid in sorted(referenced):
        if tid not in nodes:
            nodes[tid] = Node(id=tid, text=("End" if tid == "End" else ""), speaker="", type="line")

    # Prune unreachable nodes/edges to satisfy reachability constraint.
    start_id = order[0]
    adj: Dict[str, List[str]] = {}
    for e in edges:
        adj.setdefault(e.from_, []).append(e.to)

    reachable = set()
    q: deque[str] = deque([start_id])
    while q:
        cur = q.popleft()
        if cur in reachable:
            continue
        reachable.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in reachable:
                q.append(nxt)

    nodes = {nid: n for nid, n in nodes.items() if nid in reachable}
    edges = [e for e in edges if e.from_ in reachable and e.to in reachable]

    graph = {
        "nodes": [{"id": n.id, "text": n.text, "speaker": n.speaker, "type": n.type} for n in nodes.values()],
        "edges": [e.to_dict() for e in edges],
    }

    return graph


def validate_graph(graph: Dict) -> List[str]:
    errors: List[str] = []

    nodes = {n["id"] for n in graph.get("nodes", [])}
    edges = graph.get("edges", [])

    if not graph.get("nodes"):
        errors.append("Graph has no nodes")
        return errors

    for e in edges:
        src = e.get("from")
        dst = e.get("to")
        if src not in nodes:
            errors.append(f"Edge from missing node: {src}")
        if dst not in nodes:
            errors.append(f"Edge to missing node: {dst}")

    start = graph["nodes"][0]["id"]
    adj: Dict[str, List[str]] = {}
    for e in edges:
        adj.setdefault(e["from"], []).append(e["to"])

    reachable = set()
    q: deque[str] = deque([start])
    while q:
        cur = q.popleft()
        if cur in reachable:
            continue
        reachable.add(cur)
        q.extend(adj.get(cur, []))

    unreachable = nodes - reachable
    if unreachable:
        errors.append(f"Unreachable nodes: {sorted(unreachable)}")

    return errors


def graph_to_dot(graph: Dict) -> str:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    lines: List[str] = ["digraph Dialogue {", "  rankdir=LR;"]

    for n in nodes:
        nid = n["id"]
        ntype = n.get("type", "line")
        speaker = n.get("speaker", "")
        text = n.get("text", "")

        if ntype == "choice":
            shape = "diamond"
            label = nid
        else:
            shape = "box"
            if speaker and text:
                label = f"{nid}\\n{speaker}: {text}"
            elif text:
                label = f"{nid}\\n{text}"
            else:
                label = nid

        lines.append(f"  \"{_escape_dot_label(nid)}\" [shape={shape}, label=\"{_escape_dot_label(label)}\"]; ")

    for e in edges:
        src = e["from"]
        dst = e["to"]
        lbl = e.get("text") or ""
        if lbl:
            lines.append(
                f"  \"{_escape_dot_label(src)}\" -> \"{_escape_dot_label(dst)}\" [label=\"{_escape_dot_label(lbl)}\"];"
            )
        else:
            lines.append(f"  \"{_escape_dot_label(src)}\" -> \"{_escape_dot_label(dst)}\";")

    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)
    errors = validate_graph(graph)
    if errors:
        raise SystemExit("Validation failed:\n" + "\n".join(errors))

